{
  "aggregate_id": "DEF-LVMC-11-02-170::trailer",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract specifies human power, and the vehicle definition expressly excepts devices moved by human power."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "The contract specifies a motor vehicle, which cannot satisfy the requirement that a trailer be without motor power."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person, not the unpowered vehicle designed for motor-vehicle towing required by the definition."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Mass or commercial licensing does not settle motor power, towing design, or membership in the separately defined commercial-vehicle exception."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The contract requires an electric motor, contrary to the trailer definition's requirement of no motor power."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The contract describes an electrically powered scooter, contrary to the requirement that a trailer be without motor power."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation does not establish or negate the required absence of motor power and design for motor-vehicle towing."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "The fire-fighting function does not settle whether the vehicle is unpowered and designed to be drawn by a motor vehicle."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The contract specifies an engine or motor, which conflicts with the requirement that a trailer be without motor power."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The contract's self-propelled motor vehicle does not satisfy the requirement that a trailer be without motor power."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The contract expressly describes a motor vehicle, which conflicts with the no-motor-power requirement."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official or contracted road service and identifying equipment do not settle motor power or design for motor-vehicle towing."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person rather than an unpowered vehicle designed and constructed for motor-vehicle towing."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person with specified assistance, not a vehicle meeting the trailer requirements."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract requires on-track equipment but not exclusive use upon stationary rails, so the quoted exception does not establish class-wide exclusion."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "The contract specifies a designated bus, and the posted bus contract requires a motor vehicle inconsistent with being without motor power."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "A marked passenger vehicle for hire is not necessarily motor-powered under its contract, and the posted exceptions do not otherwise establish exclusion of every member."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "The lengthened-passenger-vehicle-for-hire branch does not require motor power or another disqualifying characteristic, so the words do not exclude the entire class."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "The contract encompasses potentially qualifying drawn vehicles as well as powered combinations and excepted recreational vehicles, so it does not settle the class as a whole."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "The contract specifies a bus in transit service, and the posted bus contract requires a motor vehicle inconsistent with being without motor power."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "The contract expressly requires a motor vehicle, contrary to the trailer definition's no-motor-power requirement."
    }
  ]
}

